import {
  PlaneGeometry,
  Mesh,
  MeshStandardNodeMaterial,
  Vector2,
} from 'three/webgpu';
import {
  texture,
  uv,
  positionGeometry,
  normalGeometry,
  mul,
  add,
  uniform,
  float,
  vec3,
  color,
  mix,
  normalize,
  cameraPosition,
  viewDirection,
} from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  // --- Load textures ---
  const imageTex = ctx.textureLoader.load(config.assets.imageUrl);
  const depthTex = ctx.textureLoader.load(config.assets.depthMapUrl);

  imageTex.colorSpace = 'srgb-linear';
  depthTex.colorSpace = 'linear'; // depth is grayscale

  // --- Geometry: tessellated plane (64x64) ---
  const geometry = new PlaneGeometry(1, 1, 64, 64);
  geometry.rotateX(-Math.PI / 2); // lay flat on XY plane (Z up)

  // --- Displacement node ---
  const depthValue = texture(depthTex, uv());
  const displacementAmount = uniform(0.1); // tune via props if needed
  const displacement = mul(depthValue, displacementAmount);
  const displacedPos = add(positionGeometry, mul(normalGeometry, displacement));

  // --- Material ---
  const material = new MeshStandardNodeMaterial();
  material.colorNode = texture(imageTex, uv());
  material.positionNode = displacedPos;
  material.metalnessNode = float(0.55);
  material.roughnessNode = float(0.5);

  // --- Mesh ---
  const mesh = new Mesh(geometry, material);
  const { x, y, z } = config.scenePlacement.position;
  mesh.position.set(x, y, z);
  mesh.rotation.set(
    config.scenePlacement.rotation.x,
    config.scenePlacement.rotation.y,
    config.scenePlacement.rotation.z
  );
  mesh.scale.set(
    config.scenePlacement.scale.x,
    config.scenePlacement.scale.y,
    config.scenePlacement.scale.z
  );

  // --- Store original Y for hover lift ---
  const startY = mesh.position.y;

  // --- Apply cinematic primitives (parallax-scroll) ---
  if (config.cinematicPrimitives && config.cinematicPrimitives.length) {
    config.cinematicPrimitives.forEach((primitive) => {
      const func = ctx.primitives[primitive.name];
      if (func) {
        func(mesh, primitive.params);
      }
    });
  }

  // --- Interaction handlers ---
  mesh.userData.handlers = {
    hover: (isHovered) => {
      gsap.killTweensOf(mesh.position, 'y');
      if (isHovered) {
        gsap.to(mesh.position, {
          y: startY + 0.15,
          duration: 0.5,
          ease: 'power3.out',
          overwrite: 'auto',
        });
      } else {
        gsap.to(mesh.position, {
          y: startY,
          duration: 0.5,
          ease: 'power3.out',
          overwrite: 'auto',
        });
      }
    },
    click: () => {
      gsap.to(mesh.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out',
        yoyo: true,
        repeat: 1,
        overwrite: 'auto',
      });
      // Emit event (listeners on mesh's parent or scene)
      mesh.dispatchEvent({ type: 'hub-features.select' });
    },
  };

  // --- Cleanup ---
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    imageTex.dispose();
    depthTex.dispose();
    gsap.killTweensOf(mesh.position);
    gsap.killTweensOf(mesh.scale);
  };

  return mesh;
}
